# Validaciones estrictas
print("Total registros:", len(df))
assert len(df) == 180, f"Error: esperados 180 registros, obtenidos {len(df)}"

counts = df["intencion"].value_counts().to_dict()
print("Distribución por intención:", counts)
for intent, count in counts.items():
    assert count == 45, f"Error en intención {intent}: esperado 45, obtenido {count}"

print("\nDistribución por sentimiento:\n", df["sentimiento"].value_counts())
print("\nDistribución por urgencia:\n", df["urgencia"].value_counts())

